	}

	private void initializedDataFormatModelClassMap() {
		dataFormatModelClassMap = new();
		Set<DataFormatModel> models = getDataFormatModels();
		foreach (DataFormatModel model in models) {
			dataFormatModelClassMap.put(model.getName(), model.GetType());
		}
	}

